window.TASK_BANKS[62] = {"version":1,"topicId":62,"tasks":[{"id":"62.1","codeLang":"python","answer":"[('сохранено',)]","answerLang":"text","explanation":"Закрытие соединения освобождает ресурс, но не заменяет commit. Первая запись зафиксирована, вторая откатилась при закрытии незавершённой транзакции. Файл и объект Flask имеют разное время жизни.","verified":"3.14","wrong":["[('сохранено',), ('не сохранено',)]","[]"]},{"id":"62.2","codeLang":"python","answer":"import sqlite3\nfrom contextlib import closing\ndef init_notes(path):\n    with closing(sqlite3.connect(path)) as con:\n        with con:\n            con.execute('CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, done INTEGER NOT NULL DEFAULT 0 CHECK(done IN (0,1)), version INTEGER NOT NULL DEFAULT 1 CHECK(version>0))')","answerLang":"python","explanation":"Инициализация и очистка — разные действия. CREATE TABLE IF NOT EXISTS позволяет повторно открыть приложение, сохранив записи. AUTOINCREMENT не переиспользует уже зафиксированный максимальный ID удалённой записи; это не обещание отсутствия пропусков в последовательности.","verified":"3.14","check":{"append":"import sqlite3\nfrom contextlib import closing\nfrom tempfile import TemporaryDirectory\nfrom pathlib import Path\n\nwith TemporaryDirectory() as folder:\n    path=Path(folder)/'notes.db'\n    assert init_notes(path) is None\n    with closing(sqlite3.connect(path)) as con:\n        with con:con.execute('INSERT INTO notes(title) VALUES (?)',(\"O'Neil\",))\n    init_notes(path)\n    with closing(sqlite3.connect(path)) as con:\n        assert con.execute('SELECT id,title,done,version FROM notes').fetchall()==[(1,\"O'Neil\",0,1)]\n        for sql,args in [('INSERT INTO notes(title,done) VALUES (?,?)',('X',2)),('INSERT INTO notes(title,version) VALUES (?,?)',('X',0)),('INSERT INTO notes(title) VALUES (?)',(None,))]:\n            try:\n                with con:con.execute(sql,args)\n            except sqlite3.IntegrityError:pass\n            else:raise AssertionError('Ограничение таблицы не действует')\n        with con:con.execute('DELETE FROM notes WHERE id=1')\n        with con:con.execute('INSERT INTO notes(title) VALUES (?)',('Новая',))\n        assert con.execute('SELECT id FROM notes').fetchone()[0]==2\nprint('OK')","expect":"OK"}},{"id":"62.3","codeLang":"python","answer":"42\nсоединение закрыто","answerLang":"text","explanation":"После успешного with con транзакция завершена, но соединение ещё доступно. closing вызывает close при выходе из внешнего блока. Исключение внутри транзакции нужно выпустить наружу, чтобы менеджер увидел отказ и откатил изменения.","verified":"3.14","wrong":["соединение закрыто","42\n1"]},{"id":"62.4","codeLang":"python","answer":"import sqlite3\nfrom contextlib import closing\ndef find_notes(path,title):\n    with closing(sqlite3.connect(path)) as con:\n        con.row_factory=sqlite3.Row\n        rows=con.execute('SELECT id,title,done,version FROM notes WHERE title=? ORDER BY id',(title,)).fetchall()\n        return [dict(row,done=bool(row['done'])) for row in rows]","answerLang":"python","explanation":"Параметр ? передаёт значение отдельно от SQL-программы. Апостроф не нужно экранировать вручную. Row даёт доступ по имени столбца; при сериализации флаг SQLite 0/1 явно становится JSON-совместимым bool.","verified":"3.14","check":{"append":"import sqlite3\nfrom contextlib import closing\nfrom tempfile import TemporaryDirectory\nfrom pathlib import Path\n\nwith TemporaryDirectory() as folder:\n    path=Path(folder)/'notes.db'\n    values=[(\"O'Neil\",0),(\"' OR 1=1 --\",1),('%_',0),(\"O'Neil\",1)]\n    with closing(sqlite3.connect(path)) as con:\n        con.execute('CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, done INTEGER NOT NULL DEFAULT 0 CHECK(done IN (0,1)), version INTEGER NOT NULL DEFAULT 1 CHECK(version>0))')\n        with con:con.executemany('INSERT INTO notes(title,done) VALUES (?,?)',values)\n    for title in [\"O'Neil\",\"' OR 1=1 --\",'%_','missing']:\n        expected=[{'id':i,'title':text,'done':bool(done),'version':1} for i,(text,done) in enumerate(values,1) if text==title]\n        actual=find_notes(path,title)\n        assert actual==expected and all(type(row['done']) is bool for row in actual)\n    with closing(sqlite3.connect(path)) as con:\n        assert con.execute('SELECT title,done FROM notes ORDER BY id').fetchall()==values\nprint('OK')","expect":"OK"}},{"id":"62.5","codeLang":"python","answer":"import sqlite3\nfrom contextlib import closing\ndef apply_adjustments(path,changes):\n    with closing(sqlite3.connect(path)) as con:\n        with con:\n            con.execute('BEGIN IMMEDIATE')\n            for sku,delta in changes:\n                cursor=con.execute('UPDATE stock SET qty=qty+? WHERE sku=? AND qty+?>=0',(delta,sku,delta))\n                if cursor.rowcount!=1:raise ValueError('Изменение невозможно')","answerLang":"python","explanation":"Транзакция охватывает весь пакет, а не одну строку цикла. Условный UPDATE одновременно проверяет остаток и изменяет его. ValueError должен выйти из with con: если поймать его внутри и продолжить, ранее выполненные UPDATE могут зафиксироваться.","verified":"3.14","check":{"append":"import sqlite3\nfrom contextlib import closing\nfrom tempfile import TemporaryDirectory\nfrom pathlib import Path\n\nwith TemporaryDirectory() as folder:\n    path=Path(folder)/'stock.db'\n    with closing(sqlite3.connect(path)) as con:\n        con.execute('CREATE TABLE IF NOT EXISTS stock(sku TEXT PRIMARY KEY, qty INTEGER NOT NULL CHECK(qty>=0))')\n        with con:con.executemany('INSERT INTO stock VALUES (?,?)',[(\"O'Neil\",4),('0012',0)])\n    def snapshot():\n        with closing(sqlite3.connect(path)) as con:return con.execute('SELECT sku,qty FROM stock ORDER BY sku').fetchall()\n    changes=[(\"O'Neil\",-4),('0012',2),('0012',-2)]\n    assert apply_adjustments(path,changes) is None\n    assert changes==[(\"O'Neil\",-4),('0012',2),('0012',-2)]\n    assert snapshot()==[('0012',0),(\"O'Neil\",0)]\n    for changes in [[('0012',3),('missing',1)],[('0012',3),(\"O'Neil\",-1)],[('0012',-1),('0012',2)]]:\n        before=snapshot()\n        try:apply_adjustments(path,changes)\n        except ValueError:pass\n        else:raise AssertionError('Неуспешный пакет должен дать ValueError')\n        assert snapshot()==before,'Частичный пакет нельзя сохранить'\n    assert apply_adjustments(path,[]) is None\nprint('OK')","expect":"OK"}},{"id":"62.6","codeLang":"python","answer":"True\n['closed']\nзакрыто","answerLang":"text","explanation":"get_db открывает соединение по необходимости и повторно использует его в одном контексте. Teardown освобождает ресурс, но не должен молча фиксировать незавершённую запись. Параллельные запросы не получают один общий Connection из глобальной переменной.","verified":"3.14","wrong":["False\n['closed']\nзакрыто","True\n[]\nзакрыто"]},{"id":"62.7","codeLang":"python","answer":"from flask import Flask,g\nimport sqlite3\nfrom contextlib import closing\ndef create_read_app(path):\n    app=Flask('lesson',static_folder=None)\n    def get_db():\n        if 'db' not in g:\n            g.db=sqlite3.connect(path)\n            g.db.row_factory=sqlite3.Row\n        return g.db\n    @app.teardown_appcontext\n    def close_db(error):\n        db=g.pop('db',None)\n        if db is not None:db.close()\n    @app.get('/notes')\n    def listing():\n        rows=get_db().execute('SELECT id,title,done,version FROM notes ORDER BY id').fetchall()\n        return {'items':[dict(row,done=bool(row['done'])) for row in rows]}\n    return app","answerLang":"python","explanation":"Фабрика хранит путь к файлу, а g — ресурс текущего контекста. Row нельзя просто выдать как JSON: сначала сформируйте обычные словари с точными типами. Записи читаются на каждом запросе, поэтому внешнее успешное изменение видно следующему запросу.","verified":"3.14","check":{"append":"import sqlite3\nfrom contextlib import closing\nfrom tempfile import TemporaryDirectory\nfrom pathlib import Path\n\nfrom flask import Flask as _Flask,g as _g\nwith TemporaryDirectory() as folder:\n    path=Path(folder)/'notes.db';other=Path(folder)/'other.db'\n    for file in [path,other]:\n        with closing(sqlite3.connect(file)) as con:con.execute('CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, done INTEGER NOT NULL DEFAULT 0 CHECK(done IN (0,1)), version INTEGER NOT NULL DEFAULT 1 CHECK(version>0))')\n    app=create_read_app(path);assert isinstance(app,_Flask);captured=[]\n    @app.after_request\n    def capture(response):captured.append(getattr(_g,'db',None));return response\n    c=app.test_client();r=c.get('/notes');assert r.status_code==200 and r.mimetype=='application/json' and r.get_json()=={'items':[]}\n    assert captured[-1] is not None\n    try:captured[-1].execute('SELECT 1')\n    except sqlite3.ProgrammingError:pass\n    else:raise AssertionError('Соединение запроса не закрыто')\n    with closing(sqlite3.connect(path)) as con:\n        with con:con.execute('INSERT INTO notes(title,done) VALUES (?,?)',(\"O'Neil\",1))\n    expected={'items':[{'id':1,'title':\"O'Neil\",'done':True,'version':1}]}\n    assert c.get('/notes').get_json()==expected\n    assert captured[-1] is not captured[-2]\n    assert create_read_app(path).test_client().get('/notes').get_json()==expected\n    assert create_read_app(other).test_client().get('/notes').get_json()=={'items':[]}\n    assert c.get('/missing').status_code==404 and captured[-1] is None\n    assert c.post('/notes').status_code==405\nprint('OK')","expect":"OK"}},{"id":"62.8","codeLang":"python","answer":"1 0\n(1, 2)","answerLang":"text","explanation":"Номер версии входит в условие UPDATE. Первый запрос изменил одну строку и увеличил версию; второй уже не нашёл версию 1. Конфликт — отдельный исход, а не успешная перезапись более нового состояния.","verified":"3.14","wrong":["1 1\n(0, 3)","1 0\n(0, 2)"]},{"id":"62.9","codeLang":"python","answer":"from flask import Flask,request\nimport sqlite3\nfrom contextlib import closing\ndef _payload(keys):\n    if not request.is_json:return None,({'error':'json_required'},415)\n    data=request.get_json(silent=True)\n    if type(data) is not dict or set(data)!=keys:return None,({'error':'invalid_payload'},400)\n    return data,None\n\ndef _busy(error):\n    return (getattr(error,'sqlite_errorcode',0)&255) in (sqlite3.SQLITE_BUSY,sqlite3.SQLITE_LOCKED)\n\ndef _database_error(error):\n    if _busy(error):return {'error':'db_busy'},503\n    raise error\ndef create_stock_app(path):\n    with closing(sqlite3.connect(path,timeout=.5)) as con:con.execute('CREATE TABLE IF NOT EXISTS stock(sku TEXT PRIMARY KEY, qty INTEGER NOT NULL CHECK(qty>=0))')\n    app=Flask('lesson',static_folder=None)\n    app.config['MAX_CONTENT_LENGTH']=1024\n    app.register_error_handler(sqlite3.OperationalError,_database_error)\n    @app.errorhandler(413)\n    def too_large(error):return {'error':'too_large'},413\n    @app.get('/stock')\n    def listing():\n        with closing(sqlite3.connect(path,timeout=.5)) as con:\n            return {'items':[{'sku':sku,'qty':qty} for sku,qty in con.execute('SELECT sku,qty FROM stock ORDER BY sku')]}\n    @app.post('/transfer')\n    def move():\n        data,error=_payload({'from_sku','to_sku','qty'})\n        if error is not None:return error\n        source=data['from_sku'];target=data['to_sku'];qty=data['qty']\n        if any(type(value) is not str or value!=value.strip() or not 1<=len(value)<=40 for value in (source,target)) or source==target or type(qty) is not int or not 1<=qty<=100:\n            return {'error':'invalid_payload'},400\n        try:\n            with closing(sqlite3.connect(path,timeout=.5)) as con:\n                with con:\n                    con.execute('BEGIN IMMEDIATE')\n                    if con.execute('SELECT COUNT(*) FROM stock WHERE sku IN (?,?)',(source,target)).fetchone()[0]!=2:\n                        return {'error':'not_found'},404\n                    cursor=con.execute('UPDATE stock SET qty=qty-? WHERE sku=? AND qty>=?',(qty,source,qty))\n                    if cursor.rowcount!=1:return {'error':'insufficient_stock'},409\n                    con.execute('UPDATE stock SET qty=qty+? WHERE sku=?',(qty,target))\n                    return {'from_sku':source,'to_sku':target,'qty':qty}\n        except sqlite3.OperationalError as error:\n            if _busy(error):return {'error':'db_busy'},503\n            raise\n    return app","answerLang":"python","explanation":"Правило переноса принадлежит транзакции: две записи должны зафиксироваться вместе. BEGIN IMMEDIATE занимает право записи до проверки данных, условный UPDATE не допускает отрицательный остаток. Конкурентный отказ и нехватка данных — разные исходы; клиент не должен бездумно повторять действие после неизвестного результата. Триггер в проверке воспроизводит сбой второй части переноса.","verified":"3.14","hint":"Отделите валидацию запроса от одной транзакции. Не фиксируйте списание раньше зачисления. Отказ/исключение должен освободить соединение, а неожиданные ошибки не превращаются в успешный JSON.","check":{"append":"import sqlite3\nfrom contextlib import closing\nfrom tempfile import TemporaryDirectory\nfrom pathlib import Path\n\nfrom concurrent.futures import ThreadPoolExecutor\nfrom threading import Barrier\nwith TemporaryDirectory() as folder:\n    path=Path(folder)/'stock.db'\n    app=create_stock_app(path);app.config['TESTING']=True;c=app.test_client()\n    assert c.get('/stock').get_json()=={'items':[]}\n    def reset(values):\n        with closing(sqlite3.connect(path)) as con:\n            with con:\n                con.execute('DELETE FROM stock');con.executemany('INSERT INTO stock VALUES (?,?)',values)\n    def snapshot():\n        with closing(sqlite3.connect(path)) as con:return con.execute('SELECT sku,qty FROM stock ORDER BY sku').fetchall()\n    reset([('0012',5),(\"O'Neil\",0),('ERR',2)])\n    r=c.post('/transfer',json={'from_sku':'0012','to_sku':\"O'Neil\",'qty':5})\n    assert r.status_code==200 and r.mimetype=='application/json' and r.get_json()=={'from_sku':'0012','to_sku':\"O'Neil\",'qty':5}\n    assert type(r.get_json()['qty']) is int\n    for data in [{},[],{'from_sku':'ERR','to_sku':'0012','qty':1,'extra':1}]:\n        r=c.post('/transfer',json=data);assert r.status_code==400 and r.get_json()=={'error':'invalid_payload'}\n    assert create_stock_app(path).test_client().get('/stock').get_json()=={'items':[{'sku':sku,'qty':qty} for sku,qty in snapshot()]}\n    other=Path(folder)/'other.db';assert create_stock_app(other).test_client().get('/stock').get_json()=={'items':[]}\n    before=snapshot()\n    for data,status,error in [({'from_sku':'0012','to_sku':\"O'Neil\",'qty':1},409,'insufficient_stock'),({'from_sku':\"' OR 1=1 --\",'to_sku':'ERR','qty':1},404,'not_found'),({'from_sku':'ERR','to_sku':'ERR','qty':1},400,'invalid_payload'),({'from_sku':'ERR','to_sku':'0012','qty':True},400,'invalid_payload'),({'from_sku':'ERR','to_sku':'0012','qty':0},400,'invalid_payload'),({'from_sku':'ERR','to_sku':'0012','qty':101},400,'invalid_payload'),({'from_sku':'ERR','to_sku':'0012','qty':1.0},400,'invalid_payload'),({'from_sku':'ERR','to_sku':'0012','qty':'1'},400,'invalid_payload'),({'from_sku':' ERR','to_sku':'0012','qty':1},400,'invalid_payload')]:\n        r=c.post('/transfer',json=data);assert r.status_code==status and r.get_json()=={'error':error}\n        assert snapshot()==before\n    for raw,kind,status,error in [('{','application/json',400,'invalid_payload'),('null','application/json',400,'invalid_payload'),('{}','text/plain',415,'json_required'),(' '*1025+'{}','application/json',413,'too_large')]:\n        r=c.post('/transfer',data=raw,content_type=kind);assert r.status_code==status and r.get_json()=={'error':error}\n        assert snapshot()==before\n    with closing(sqlite3.connect(path)) as con:\n        con.execute(\"CREATE TRIGGER fail_update BEFORE UPDATE OF qty ON stock WHEN NEW.sku='ERR' BEGIN SELECT RAISE(ABORT,'synthetic'); END\")\n    for source,target in [(\"O'Neil\",'ERR'),('ERR',\"O'Neil\")]:\n        try:c.post('/transfer',json={'from_sku':source,'to_sku':target,'qty':1})\n        except sqlite3.IntegrityError:pass\n        else:raise AssertionError('Неожиданную ошибку БД нельзя прятать')\n        assert snapshot()==before,'Вторая ошибка должна откатить первую запись'\n    with closing(sqlite3.connect(path)) as con:con.execute('DROP TRIGGER fail_update')\n    for _ in range(2):\n        reset([('A',5),('B',0),('C',0)]);barrier=Barrier(2)\n        apps=[create_stock_app(path),create_stock_app(path)]\n        def attempt(index):\n            barrier.wait(timeout=3)\n            return apps[index].test_client().post('/transfer',json={'from_sku':'A','to_sku':['B','C'][index],'qty':5}).status_code\n        with ThreadPoolExecutor(max_workers=2) as pool:statuses=list(pool.map(attempt,range(2)))\n        assert statuses.count(200)==1 and all(status in (200,409,503) for status in statuses)\n        assert sum(qty for sku,qty in snapshot())==5 and dict(snapshot())['A']==0\n    with closing(sqlite3.connect(path)) as locker:\n        locker.execute('BEGIN IMMEDIATE')\n        r=c.post('/transfer',json={'from_sku':'B','to_sku':'C','qty':1})\n        assert r.status_code==503 and r.get_json()=={'error':'db_busy'}\n        locker.rollback()\n        locker.execute('BEGIN EXCLUSIVE')\n        r=c.get('/stock');assert r.status_code==503 and r.get_json()=={'error':'db_busy'}\n        locker.rollback()\n    assert c.get('/transfer').status_code==405 and c.post('/stock').status_code==405\n    with closing(sqlite3.connect(path)) as con:con.execute('DROP TABLE stock')\n    try:c.get('/stock')\n    except sqlite3.OperationalError:pass\n    else:raise AssertionError('Ошибка схемы не является пустым результатом или db_busy')\nprint('OK')","expect":"OK"}},{"id":"62.10","codeLang":"python","answer":"from flask import Flask,request\nimport sqlite3\nfrom contextlib import closing\ndef _payload(keys):\n    if not request.is_json:return None,({'error':'json_required'},415)\n    data=request.get_json(silent=True)\n    if type(data) is not dict or set(data)!=keys:return None,({'error':'invalid_payload'},400)\n    return data,None\n\ndef _busy(error):\n    return (getattr(error,'sqlite_errorcode',0)&255) in (sqlite3.SQLITE_BUSY,sqlite3.SQLITE_LOCKED)\n\ndef _database_error(error):\n    if _busy(error):return {'error':'db_busy'},503\n    raise error\ndef create_notes_app(path):\n    with closing(sqlite3.connect(path,timeout=.5)) as con:con.execute('CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, done INTEGER NOT NULL DEFAULT 0 CHECK(done IN (0,1)), version INTEGER NOT NULL DEFAULT 1 CHECK(version>0))')\n    app=Flask('lesson',static_folder=None)\n    app.config['MAX_CONTENT_LENGTH']=1024\n    app.register_error_handler(sqlite3.OperationalError,_database_error)\n    @app.errorhandler(413)\n    def too_large(error):return {'error':'too_large'},413\n    def connect():\n        con=sqlite3.connect(path,timeout=.5);con.row_factory=sqlite3.Row\n        return con\n    def row_data(row):return dict(row,done=bool(row['done']))\n    @app.get('/notes')\n    def listing():\n        with closing(connect()) as con:return {'items':[row_data(row) for row in con.execute('SELECT id,title,done,version FROM notes ORDER BY id')]}\n    @app.post('/notes')\n    def create():\n        data,error=_payload({'title'})\n        if error is not None:return error\n        if type(data['title']) is not str or not 1<=len(data['title'].strip())<=80:return {'error':'invalid_payload'},400\n        try:\n            with closing(connect()) as con:\n                with con:\n                    cursor=con.execute('INSERT INTO notes(title) VALUES (?)',(data['title'].strip(),))\n                    row=con.execute('SELECT id,title,done,version FROM notes WHERE id=?',(cursor.lastrowid,)).fetchone()\n                return row_data(row),201,{'Location':'/notes/'+str(row['id'])}\n        except sqlite3.OperationalError as error:\n            if _busy(error):return {'error':'db_busy'},503\n            raise\n    @app.get('/notes/<int:note_id>')\n    def read(note_id):\n        with closing(connect()) as con:row=con.execute('SELECT id,title,done,version FROM notes WHERE id=?',(note_id,)).fetchone()\n        if row is None:return {'error':'not_found'},404\n        return row_data(row)\n    @app.patch('/notes/<int:note_id>')\n    def update(note_id):\n        data,error=_payload({'done','version'})\n        if error is not None:return error\n        if type(data['done']) is not bool or type(data['version']) is not int or data['version']<1:return {'error':'invalid_payload'},400\n        try:\n            with closing(connect()) as con:\n                with con:\n                    con.execute('BEGIN IMMEDIATE')\n                    row=con.execute('SELECT id,title,done,version FROM notes WHERE id=?',(note_id,)).fetchone()\n                    if row is None:return {'error':'not_found'},404\n                    if row['version']!=data['version']:return {'error':'version_conflict'},409\n                    con.execute('UPDATE notes SET done=?,version=version+1 WHERE id=? AND version=?',(int(data['done']),note_id,data['version']))\n                    updated=con.execute('SELECT id,title,done,version FROM notes WHERE id=?',(note_id,)).fetchone()\n                return row_data(updated)\n        except sqlite3.OperationalError as error:\n            if _busy(error):return {'error':'db_busy'},503\n            raise\n    return app","answerLang":"python","explanation":"Сохранение файла не решает конфликт редактирования само по себе. Версия связывает изменение с прочитанным клиентом состоянием, а транзакция не даёт двум писателям одновременно принять одну старую версию. 409 нужно показать как конфликт и перечитать данные; слепой повтор старого изменения не является безопасным объединением.","verified":"3.14","hint":"Запрос содержит ожидаемую версию. Проверка версии и запись должны принадлежать одной транзакции; статус конфликта не должен сопровождаться изменённым done или увеличенным version.","check":{"append":"import sqlite3\nfrom contextlib import closing\nfrom tempfile import TemporaryDirectory\nfrom pathlib import Path\n\nfrom concurrent.futures import ThreadPoolExecutor\nfrom threading import Barrier\nwith TemporaryDirectory() as folder:\n    path=Path(folder)/'notes.db'\n    app=create_notes_app(path);app.config['TESTING']=True;c=app.test_client()\n    assert c.get('/notes').get_json()=={'items':[]}\n    for title in [\"  O'Neil  \",\"'); DROP TABLE notes; --\"]:\n        r=c.post('/notes',json={'title':title});id=r.get_json()['id']\n        assert r.status_code==201 and r.mimetype=='application/json'\n        assert r.get_json()=={'id':id,'title':title.strip(),'done':False,'version':1}\n        assert type(id) is int and type(r.get_json()['done']) is bool and type(r.get_json()['version']) is int\n        assert r.headers.get('Location')=='/notes/'+str(id)\n    second=create_notes_app(path).test_client()\n    assert second.get('/notes').get_json()==c.get('/notes').get_json()\n    assert all(type(row['done']) is bool and type(row['id']) is int and type(row['version']) is int for row in c.get('/notes').get_json()['items'])\n    assert create_notes_app(Path(folder)/'other.db').test_client().get('/notes').get_json()=={'items':[]}\n    before=c.get('/notes').get_json()\n    for data in [{},{'title':''},{'title':'x'*81},{'title':True},{'title':'X','done':False}]:\n        r=c.post('/notes',json=data);assert r.status_code==400 and r.get_json()=={'error':'invalid_payload'}\n        assert c.get('/notes').get_json()==before\n    for raw,kind,status,error in [('{','application/json',400,'invalid_payload'),('null','application/json',400,'invalid_payload'),('{}','text/plain',415,'json_required'),(' '*1025+'{}','application/json',413,'too_large')]:\n        for method,url in [('post','/notes'),('patch','/notes/1')]:\n            r=getattr(c,method)(url,data=raw,content_type=kind);assert r.status_code==status and r.get_json()=={'error':error}\n        assert c.get('/notes').get_json()==before\n    for data in [{'done':0,'version':1},{'done':True,'version':True},{'done':True,'version':0},{'done':True,'version':'1'},{'done':False,'version':1,'extra':1}]:\n        r=c.patch('/notes/1',json=data);assert r.status_code==400 and r.get_json()=={'error':'invalid_payload'}\n    first={'id':1,'title':\"O'Neil\",'done':True,'version':2}\n    r=c.patch('/notes/1',json={'done':True,'version':1});assert r.status_code==200 and r.get_json()==first and type(r.get_json()['done']) is bool\n    r=second.patch('/notes/1',json={'done':False,'version':1});assert r.status_code==409 and r.get_json()=={'error':'version_conflict'}\n    assert second.get('/notes/1').get_json()==first\n    r=c.patch('/notes/999',json={'done':False,'version':1});assert r.status_code==404 and r.get_json()=={'error':'not_found'}\n    r=c.patch('/notes/999',json={});assert r.status_code==400 and r.get_json()=={'error':'invalid_payload'}\n    barrier=Barrier(2);apps=[create_notes_app(path),create_notes_app(path)]\n    def attempt(index):\n        barrier.wait(timeout=3)\n        return apps[index].test_client().patch('/notes/1',json={'done':bool(index),'version':2}).status_code\n    with ThreadPoolExecutor(max_workers=2) as pool:statuses=list(pool.map(attempt,range(2)))\n    assert statuses.count(200)==1 and all(status in (200,409,503) for status in statuses)\n    assert c.get('/notes/1').get_json()['version']==3\n    assert create_notes_app(path).test_client().get('/notes/1').get_json()==c.get('/notes/1').get_json()\n    with closing(sqlite3.connect(path)) as locker:\n        locker.execute('BEGIN IMMEDIATE')\n        r=c.patch('/notes/1',json={'done':False,'version':3})\n        assert r.status_code==503 and r.get_json()=={'error':'db_busy'}\n        locker.rollback()\n        locker.execute('BEGIN EXCLUSIVE')\n        for url in ['/notes','/notes/1']:\n            r=c.get(url);assert r.status_code==503 and r.get_json()=={'error':'db_busy'}\n        locker.rollback()\n    for title in ['я'*80,'Третья']:\n        r=c.post('/notes',json={'title':title});assert r.status_code==201\n    assert [r['id'] for r in c.get('/notes').get_json()['items']]==[1,2,3,4]\n    assert c.get('/notes/0').status_code==404 and c.put('/notes/1').status_code==405\n    with closing(sqlite3.connect(path)) as con:con.execute('DROP TABLE notes')\n    try:c.get('/notes')\n    except sqlite3.OperationalError:pass\n    else:raise AssertionError('Неожиданную ошибку схемы нельзя скрывать')\nprint('OK')","expect":"OK"}}]};
